const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_5","ls":"6.5","title":"Lernpfadübung · LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","version":"1.0","source":"Fachbereiche/BFSdual/LF06/LS_6_5_Werbeaktion_planen.md"};
const COMP=[["Fachkompetenz","Ich vereinbare mit zwei Handelspartnern ein Werbeziel, das wir überprüfen können. Ich stimme passende Werbeträger und feste Termine ab. Ich kläre, welche Aufgaben der Großhandel und welche die beiden Läden übernehmen."],["Personalkompetenz","Ich habe die Fristen im Blick und prüfe, ob ich meine Zusagen einhalten kann."],["Sozialkompetenz","Ich höre, was den Beteiligten wichtig ist. Ich helfe, feste Absprachen zu finden."],["Methodenkompetenz","Ich halte Ziel, Maßnahmen und Termine in einem gemeinsamen Plan fest."],["Medienkompetenz","Ich wähle einen Werbeträger, der die gewünschte Kundschaft am jeweiligen Standort erreicht."]];
const BANK=[{"title":"Werbung für Block","scene":"Das 2-Rad Center Block ist ein Fahrradgeschäft in Aurich. Viele Kundinnen und Kunden fahren im Alltag Rad und kommen nach der Arbeit zur Beratung.","ask":"Was passt laut M1 zur Kundschaft von Block?","options":["Ein Newsletter kann Menschen erreichen, die schon Kontakt zu Block hatten.","Kundschaft aus dem Alltag ist für Block unwichtig.","Ein Hinweis vor dem Besuch kann zur Beratung einladen.","Die meisten angesprochenen Personen kommen laut M1 erst am Samstag.","Der Aufsteller in Leer erreicht Blocks Newsletter-Empfänger direkt.","Block möchte nur Verkäufe beobachten und zählt keine Beratungen."],"answer":[0,2],"why":"Der Newsletter erreicht bereits bekannte Kundschaft und kann zu persönlicher Beratung im Laden einladen. Block kann Beratungen zusätzlich zählen.","hint":"Prüfe, wann und weshalb die Menschen zu Block kommen.","steps":"Lies Blocks Zeile in M1. Unterscheide Kontakt vor dem Besuch und Kontakt im Laden.","example":"Eine Nachricht am Morgen kann auf einen Besuch nach der Arbeit vorbereiten.","c":4,"sourceRefs":["M1","M4"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Werbung in Leer","scene":"Die Bike Arena Oltmanns ist ein Fahrradgeschäft in Leer. Im Fall wählen viele Menschen das Zubehör auf einer Aktionsfläche selbst aus.","ask":"Welche Aussagen über die Zielgruppe und den Standort treffen zu?","options":["Fast alle Interessierten brauchen zuerst einen persönlichen Beratungstermin.","Familien und Menschen, die in der Freizeit Rad fahren, sind wichtige Zielgruppen.","Vor allem am Samstag kommen Familien in die Bike Arena.","Der Newsletter von Block ist der vorgesehene Werbeträger für Leer.","Die geplante Aktionsfläche richtet sich nur an Kundschaft, die schon bestellt hat.","Am Eingang oder Hauptgang lassen sich Menschen beim Einkauf auf die Aktion aufmerksam machen."],"answer":[1,2,5],"why":"Samstag ist für Familien besonders wichtig. Eingang und Hauptgang sind im Fall gut besuchte Werbeplätze, von denen Kundschaft zur Auswahlfläche gelangen kann.","hint":"Achte auf die Besuchszeit und die Plätze im Laden.","steps":"Vergleiche die Zeile der Bike Arena in M1 mit ihrer Stimme in M4.","example":"Ein Hinweis am Eingang kann eine Familie erreichen, bevor sie an Regalen vorbeigeht.","c":4,"sourceRefs":["M1","M4"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Werbeträger und Werbemittel","scene":"In M3 steht für jeden Werbeplatz auch die dazu passende gestaltete Werbung.","ask":"Welche Zuordnungen stimmen?","options":["Der fertige Werbebeitrag ist der Werbeträger für den E-Mail-Versand.","Das gedruckte Schild ist ein Werbemittel.","Ein Newsletter kann einen Werbebeitrag als Werbeträger verbreiten.","Der Aufsteller am Eingang ist das bedruckte Werbemittel selbst.","Das Schaufenster kann als Werbeträger für einen Aushang dienen.","Der Hauptgang ist der Einsatztermin des Schildes."],"answer":[1,2,4],"why":"Werbeträger verbreiten die Werbung oder geben ihr einen Platz. Ein Textbeitrag, ein Aushang oder ein bedrucktes Schild ist das gestaltete Werbemittel.","hint":"Frage zweimal: Was wird gestaltet? Wo erscheint es?","steps":"Markiere in M3 zuerst den Platz oder das Medium, dann das gestaltete Stück Werbung.","example":"Ein Plakatrahmen trägt das Plakat, das darin zu sehen ist.","c":4,"sourceRefs":["M3","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ziel oder Wunsch?","scene":"Jan Richter will vor dem Start wissen, woran beide Geschäfte erkennen, ob die Frühjahrsaktion ihr Ziel erreicht.","ask":"Welche Bausteine braucht ein überprüfbares Werbeziel?","options":["Eine Kennzahl, die beide Standorte erfassen können.","Einen Zielwert, den die Beteiligten vorher abstimmen.","Eine Aussage, dass beide Geschäfte mehr Aufmerksamkeit wollen.","Die technische Druckauflösung der Werbemittel.","Einen Zeitraum für die Messung.","Den Namen der zuletzt zuständigen Druckerei."],"answer":[0,1,4],"why":"Ein überprüfbares Ziel legt fest, was gemessen wird, welcher Wert erreicht werden soll und für welchen Zeitraum dieser Wert gilt.","hint":"Überlege, worüber Jan nach der Aktion entscheiden können soll.","steps":"Prüfe bei jedem Vorschlag: Hilft die Angabe zu entscheiden, ob das Ziel erreicht wurde?","example":"Ein Zielwert von 50 Stück ist erst mit Produktgruppe und Zeitraum eindeutig.","c":0,"sourceRefs":["M2","M6"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine Kennzahl für beide","scene":"Block möchte Beratungen zählen. Die Bike Arena möchte Verkäufe zählen und hat im Fall keine verlässlichen Beratungszahlen.","ask":"Welche Folgerungen sind für das gemeinsame Ziel sinnvoll?","options":["Beratungen bei Block und Stückzahlen in Leer lassen sich als dieselbe Kennzahl addieren.","Die Läden können die verkauften Stücke des Aktionssortiments einheitlich zählen.","Die Bike Arena kann fehlende Beratungszahlen einfach schätzen.","Block darf seine Beratungszahlen zusätzlich für den eigenen Laden betrachten.","Die Öffnungszeiten allein reichen als Kennzahl für den Verkaufserfolg.","Der Umsatz aller Warengruppen ist laut M2 die vereinbarte Kennzahl."],"answer":[1,3],"why":"Verkaufte Aktionsartikel sind für beide Läden verfügbar. Beratungszahlen helfen Block bei einer eigenen Frage, tragen aber keinen gemeinsamen Vergleich.","hint":"Beide Läden müssen dieselbe Größe erfassen können.","steps":"Stell die vorhandenen Daten beider Standorte nebeneinander. Prüfe, welche Messgröße in beiden Spalten steht.","example":"Verkaufte Stücke und geführte Beratungen sind zwei verschiedene Größen.","c":0,"sourceRefs":["Handlungssituation","M2"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ausgangszahlen","scene":"Jan will die Verkäufe der Aktionswoche mit einer früheren Woche vergleichen.","ask":"Welche Angaben gehören zur Ausgangslage aus M2?","options":["Block verkaufte 60 Stück aus dem Aktionssortiment.","Die Bike Arena verkaufte 60 Stück aus dem Aktionssortiment.","Block verkaufte 40 Stück aus dem Aktionssortiment.","Die Zahl 40 bezeichnet die Beratungen bei Block.","Die früheren Stückzahlen sind bereits die Werte der Aktionswoche.","Beide Läden hatten in der Vergleichswoche an denselben Tagen geöffnet."],"answer":[1,2,5],"why":"Die Ausgangswerte sind 40 Stück bei Block und 60 Stück in der Bike Arena. Gleiche Öffnungstage machen die Wochen vergleichbarer.","hint":"Lies die Zahlen zusammen mit ihrem Zeitraum und ihrer Einheit.","steps":"Schreib für beide Standorte die Stückzahl auf. Prüfe dann die Öffnungstage im gleichen Absatz.","example":"40 Stück sind eine Absatzmenge. 40 Kundengespräche wären eine andere Größe.","c":3,"sourceRefs":["M2","M4"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Newsletter im Kalender","scene":"Block möchte mit seinem E-Mail-Newsletter zur Beratung einladen.","ask":"Welche Angaben gehören in den Terminplan für diesen Newsletter?","options":["Die Ladenleitung genehmigt den Text bis Donnerstag um 12 Uhr in der Vorbereitungswoche.","Die Druckerei genehmigt und verschickt den Newsletter.","Block verschickt den Newsletter am Montag um 8 Uhr vor dem Verkaufsstart.","Die Freigabe ist erst am Montag nach dem Verschicken fällig.","Der Newsletter ersetzt die Meldung der Verkaufszahlen.","Block plant und verschickt den Newsletter selbst."],"answer":[0,2,5],"why":"Die Ladenleitung von Block gibt den Beitrag bis Donnerstagmittag frei. Block versendet ihn am folgenden Montagmorgen, bevor der Verkauf am Dienstag beginnt.","hint":"Lies die Newsletter-Zeile in M3 bis zum Ende.","steps":"Teile die Zeile in drei Fragen auf: Wer gibt frei, bis wann und wann erscheint der Beitrag?","example":"Ein Newsletter kann vor dem ersten Verkaufstag ankündigen, was ab Dienstag erhältlich ist.","c":1,"sourceRefs":["M3"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eingangsschild in Leer","scene":"Die Bike Arena hat einen Platz für den Aufsteller am Eingang eingeplant.","ask":"Welche Angaben müssen für diesen Aufsteller stimmen?","options":["Freigabe bis Freitag um 12 Uhr, weil die Bike Arena das Eingangsschild selbst druckt.","Die Bike Arena meldet der Druckerei die Freigabe bis Mittwoch um 16 Uhr.","Die Druckerei liefert bis Donnerstag der Aktionswoche.","Global Bike stellt das Schild am Montag am Eingang auf.","Das bedruckte Schild steht ab Freitag der Aktionswoche am Eingang.","Die Materiallieferung durch Sarah ersetzt die Druckfreigabe."],"answer":[1,2,4],"why":"Für den Eingang ist die Druckerei eingeplant. Die Bike Arena erteilt ihr am Mittwoch bis 16 Uhr die Freigabe. Nach der Lieferung stellt der Laden das Schild ab Freitag auf.","hint":"Unterscheide den Eingang vom Werbeplatz am Hauptgang.","steps":"Folge der Zeile für den Aufsteller am Eingang von Druckfreigabe über Lieferung bis zum Einsatz.","example":"Ein Schild kann einen Tag vor dem Aufstellen geliefert werden.","c":1,"sourceRefs":["M3","M4"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zusammenarbeit planen","scene":"Global Bike und zwei Fahrradgeschäfte planen eine gemeinsame Frühjahrsaktion.","ask":"Woran erkennt man kooperative Werbung in diesem Fall?","options":["Alle drei Partner vereinbaren ein gemeinsames Ziel.","Die Druckerei legt die Verkaufsziele und die Produkte fest.","Jeder Laden veröffentlicht ohne Abstimmung seine eigene Aktion.","Global Bike liefert Produktangaben, die Läden prüfen ihre jeweilige Fassung.","Beide Standorte müssen dasselbe Werbemittel nutzen, damit es eine Kooperation ist.","Die Läden stimmen Aufgaben und Fristen mit Global Bike ab."],"answer":[0,3,5],"why":"Ein gemeinsames Ziel, abgestimmte Aufgaben und eigene Beiträge der Partner kennzeichnen die Zusammenarbeit. Die Werbemittel dürfen zum jeweiligen Standort passen.","hint":"Schau, welche Beiträge sich zwischen den Partnern ergänzen.","steps":"Notiere je Partner einen Beitrag. Prüfe, ob die Beteiligten ein gemeinsames Ergebnis vorbereiten.","example":"Eine gemeinsame Aktion kann an einem Standort per Nachricht und am anderen per Schild angekündigt werden.","c":2,"sourceRefs":["M3","M6"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Freigabe und Einsatz","scene":"In dem Werbeplan stehen eine Freigabefrist und ein Einsatztermin.","ask":"Welche Erklärungen helfen den Beteiligten, die beiden Angaben auseinanderzuhalten?","options":["Der Einsatztermin gibt an, wann Kundinnen und Kunden die Werbung sehen können.","Die Freigabefrist nennt den spätesten Zeitpunkt für die Zustimmung.","Beim Eingangsschild ersetzt der Tag des Aufstellens die Nachricht an die Druckerei.","Die Freigabefrist fällt grundsätzlich mit dem Ende der Aktion zusammen.","Die Werbung kann später erscheinen, als sie freigegeben wurde.","Der Einsatztermin gibt vor, wann die Verkaufszahlen gemeldet werden."],"answer":[0,1,4],"why":"Die Freigabe liegt so früh, dass Herstellung oder Versand noch möglich sind. Der Einsatztermin markiert, ab wann die Werbung sichtbar ist.","hint":"Frag bei jedem Datum, was an dem Tag tatsächlich passiert.","steps":"Nutze die Termine für den Aufsteller als Beispiel und ordne jeden einem Arbeitsschritt zu.","example":"Bei einem Druckauftrag liegt die Zustimmung für die Druckerei vor der Lieferung.","c":1,"sourceRefs":["M3","M6"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Aufgaben klar verteilen","scene":"Global Bike bereitet Daten und Entwürfe vor. Die Läden entscheiden über ihre Fassungen.","ask":"Welche Zuständigkeiten sind im Werbeplan richtig zugeordnet?","options":["Jan koordiniert bei Global Bike die Absprachen.","Sarah setzt beide Werbemittel selbst vor Ort ein.","Die Ladenleitungen prüfen die Angaben sowie den Platz und geben ihre jeweilige Fassung frei.","Die Druckerei meldet nach der Aktion die Kassenverkäufe aus Leer.","Block meldet für beide Läden die Gesamtzahlen ohne Rücksprache.","Sarah stellt am Mittwoch ab 10 Uhr Produktinformationen und Bilder bereit."],"answer":[0,2,5],"why":"Sarah liefert die Unterlagen, Jan koordiniert und jede Ladenleitung verantwortet die eigene Freigabe. Die Läden melden ihre Verkäufe jeweils selbst.","hint":"Trenne Koordination, Vorbereitung, Freigabe und Rückmeldung.","steps":"Gehe in M3 nacheinander Sarahs, Jans und die Aufgaben der Ladenleitungen durch.","example":"Wer einen Entwurf liefert, erteilt damit noch keine Freigabe für einen Laden.","c":2,"sourceRefs":["M3","M4"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Erfolg nachsehen","scene":"In M2 ist der Montag nach der Frühjahrsaktion für die Meldung der Ergebnisse vorgesehen.","ask":"Welche Informationen braucht Global Bike für die Erfolgskontrolle?","options":["Die in der Aktionswoche verkauften Stücke je Laden.","Die Namen aller Personen, die ein Fahrradgeschäft besucht haben.","Die vereinbarten Zielwerte und passenden Ausgangsmengen.","Die Werbemaßnahme, die der anderen Niederlassung am besten gefallen hat.","Die Beratungen von Block als Ersatz für fehlende Stückzahlen.","Information darüber, auf welche Woche die Zahlen sich beziehen."],"answer":[0,2,5],"why":"Ausgangswert, Zielwert, gemessene Stückzahl und der passende Zeitraum machen die Kontrolle möglich. Die Läden melden ihre Stückzahlen getrennt.","hint":"Denk an die Daten, die sich nach der Aktion mit dem Plan vergleichen lassen.","steps":"Notiere in einer Zeile je Laden Altwert, Ziel, Aktionswert und Zeitraum.","example":"Eine Gesamtzahl ohne Standort oder Woche reicht für getrennte Ladenvergleiche nicht.","c":3,"sourceRefs":["M2","M5"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Machbares gemeinsames Ziel","scene":"Aus M2: Block verkaufte in der Vergleichswoche 40, die Bike Arena 60 Stück aus dem Aktionssortiment.","ask":"Welche Vorschläge sind als gemeinsames Werbeziel vollständig und mit M2 überprüfbar?","options":["In beiden Läden soll die Frühjahrsaktion gut ankommen.","In der Aktionswoche sollen aus dem Aktionssortiment bei Block mindestens 44 und in der Bike Arena mindestens 66 Stück verkauft werden.","Beide Läden sollen im Frühjahr ungefähr zehn mehr erreichen.","Der Newsletter soll in der Vorbereitungswoche bis Donnerstag freigegeben sein.","In der Aktionswoche sollen die Verkäufe der Aktionsartikel bei beiden Läden um mindestens 10 % über der Vergleichswoche liegen.","Die Läden sollen in der Aktionswoche jeweils mindestens 20 Kundengespräche führen und für das gemeinsame Ergebnis erfassen."],"answer":[1,4],"why":"44 und 66 Stück sind die Zielwerte bei jeweils 10 % Zuwachs. Beide Formulierungen nennen eine messbare Größe, ihren Zielwert und den passenden Zeitraum.","hint":"Suche jede der drei Angaben und prüfe, ob beide Läden die Zahl haben.","steps":"Unterstreiche in jeder Formulierung, was, wie viel und wann gemessen wird. Gleiche es mit M2 ab.","example":"Ein Versandtermin ist überprüfbar, beantwortet aber nicht die gewünschte Frage nach der Verkaufsentwicklung.","c":0,"sourceRefs":["M2","M5"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Von Prozent zu Stück","scene":"Übungsvariante: Die Partner wollen in jedem Laden mindestens 15 % mehr aus dem Aktionssortiment verkaufen als in der Vergleichswoche.","ask":"Welche Einträge im Plan stimmen rechnerisch oder helfen bei der späteren Kontrolle?","options":["Block: mindestens 46 Stück.","Bike Arena: mindestens 65 Stück.","Block: mindestens 55 Stück, weil 15 % gleich 15 Stück sind.","Bike Arena: mindestens 69 Stück.","Als Ausgangswerte 40 und 60 Stück getrennt aufschreiben.","Die Zielwerte sind 6 und 9 Stück insgesamt, weil nur der Zuwachs zählt."],"answer":[0,3,4],"why":"15 % von 40 sind 6, 15 % von 60 sind 9. Die Zielwerte sind 46 und 69 Stück. Die getrennten Ausgangswerte gehören zur Erfolgskontrolle.","hint":"Rechne pro Laden zuerst den Zuwachs und danach den Zielwert.","steps":"Multipliziere jede Ausgangsmenge mit 0,15 und addiere das Ergebnis zu dieser Ausgangsmenge.","example":"Bei 20 Stück Ausgangsmenge ergeben 15 % Zuwachs insgesamt 23 Stück.","c":3,"sourceRefs":["M2","M5"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Vor dem Besuch oder im Laden","scene":"Übungsvariante: Block will seine bekannte Kundschaft vor dem Ladenbesuch zur Beratung einladen. Die Bike Arena möchte am Samstag Menschen gleich beim Betreten erreichen.","ask":"Welche beiden Plätze erfüllen diese Absichten in M3 am direktesten?","options":["Block: Aushang im Schaufenster ab Dienstag, der am besten beim Vorbeigehen wirkt.","Bike Arena: erst am Montag nach der Aktion über das Schild berichten.","Block: Versand des E-Mail-Newsletters am Montag um 8 Uhr.","Bike Arena: Aufsteller am Eingang ab Freitag, also auch am Samstag.","Bike Arena: Schild am Hauptgang, auch wenn ausdrücklich der erste Eindruck am Eingang zählen soll.","Block: erst am Samstag einen Hinweis in der Bike Arena aufstellen."],"answer":[2,3],"why":"Der Newsletter erreicht bekannte Kundschaft vor dem Besuch. Der Aufsteller steht am Samstag schon am Eingang der Bike Arena und erreicht dort die ankommenden Menschen.","hint":"Überlege, an welcher Stelle im Weg der Kundschaft die Werbung ankommen soll.","steps":"Markiere die beiden Zeitpunkte: vor dem Besuch und beim Betreten. Vergleiche beide mit M1 und M3.","example":"Ein Aushang wirkt erst dort, wo Menschen an ihm vorbeikommen.","c":4,"sourceRefs":["M1","M3"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Aufsteller rechtzeitig vorbereiten","scene":"Sarah kann der Bike Arena bis Mittwoch um 14 Uhr ihren Entwurf schicken. Die Druckerei braucht die Freigabe bis 16 Uhr.","ask":"Was muss Jan in dem verbleibenden Zeitfenster abstimmen?","options":["Die Ladenleitung der Bike Arena ist zwischen Entwurf und Freigabefrist ansprechbar.","Die Druckerei soll das Schild schon vor der Freigabe fertig drucken.","Die Ladenleitung hat Zeit, Platz und Produktangaben zu prüfen.","Global Bike gibt ohne Ladenleitung den Entwurf als verbindlich aus.","Die Ladenleitung meldet ihre Freigabe bis 16 Uhr an die Druckerei.","Die Freigabe kann wegen des Einsatzes am Freitag der Aktionswoche erst dann erfolgen."],"answer":[0,2,4],"why":"Zwischen 14 und 16 Uhr bleiben höchstens zwei Stunden für Prüfung und Rückmeldung der Ladenleitung. Die Druckerei muss ihre Freigabe in diesem Fenster erhalten.","hint":"Ordne die Frist der Prüfung zu, die ihr vorausgehen muss.","steps":"Markiere 14 Uhr und 16 Uhr auf einer Zeitachse und setze die Prüfung und die Meldung dazwischen.","example":"Einen Termin einzuplanen hilft erst, wenn die zuständige Person in dem Zeitfenster verfügbar ist.","c":1,"sourceRefs":["M3","M4"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Wechsel zum Hauptgang","scene":"Übungsvariante: Die Bike Arena verpasst die Mittwochsfrist für den Aufsteller am Eingang. Die Möglichkeit am Hauptgang aus M3 ist noch verfügbar.","ask":"Welche Änderungen gehören in die neue Planzeile?","options":["Auf den Werbeplatz am Hauptgang mit einem gedruckten Hinweisschild wechseln.","Den Eingangstermin Freitag unverändert übernehmen, obwohl das Hauptgangschild früher bereitstehen kann.","Die Freigabe der Bike Arena bis Freitag um 12 Uhr in der Vorbereitungswoche eintragen.","Die Druckerei für das Hauptgangschild verpflichtend erneut beauftragen.","Die Bike Arena druckt das Schild selbst und bringt es zur Öffnung am Dienstag an.","Die gemeinsame Kennzahl bei diesem Wechsel automatisch von Absatz auf Beratungszahl ändern."],"answer":[0,2,4],"why":"Für den Hauptgang gelten ein anderer Platz, eigener Druck, Freigabe bis Freitagmittag und Einsatz ab Dienstag zur Öffnung. Das gemeinsame Verkaufsziel bleibt bei einem Wechsel des Platzes vergleichbar.","hint":"Vergleiche beide Werbeplätze in M3 Zeile für Zeile.","steps":"Streiche nur die alten Eingangsschritte. Übertrage die Termine und Zuständigkeiten des Hauptgangschilds.","example":"Ein geänderter Werbeplatz verlangt eine neue Zeitachse, aber keine neue Kennzahl, solange das Ziel gleich bleibt.","c":3,"sourceRefs":["M2","M3"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zusagen sauber festhalten","scene":"Übungsvariante: Im Gespräch sagen die beiden Ladenleitungen, dass ihre Fristen eingehalten werden können, wenn die Entwürfe am Mittwoch um 14 Uhr da sind.","ask":"Welche Formulierungen könnte Jan direkt in eine Gesprächsnotiz übernehmen?","options":["Die Ladenleitung der Bike Arena prüft das Eingangsschild und meldet der Druckerei ihre Freigabe bis Mittwoch 16 Uhr.","Beide Läden kümmern sich irgendwann um alles Nötige.","Global Bike schickt bis Mittwoch 14 Uhr je einen Entwurf an beide Ladenleitungen.","Sarah prüft nebenbei, ob irgendwann ein Platz frei ist.","Block gibt den Newsletter-Text durch seine Ladenleitung bis Donnerstag 12 Uhr frei und versendet Montag 8 Uhr.","Die Ladenzusagen brauchen keinen Zeitpunkt, da beide im Gespräch zugestimmt haben."],"answer":[0,2,4],"why":"Verbindliche Absprachen nennen Verantwortliche, Handlung und Termin. So erkennen alle, was sie bis wann zusagen und wer auf die Erledigung wartet.","hint":"Achte auf drei Angaben: wer, was und bis wann.","steps":"Prüfe jede Formulierung mit diesen drei Fragen. Markiere leere oder unklare Angaben.","example":"„Drucken“ reicht nicht, wenn weder klar ist, wer druckt, noch bis wann.","c":2,"sourceRefs":["M3","M4","M5"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Interessen unterbringen","scene":"Block möchte Beratungen sichtbar machen. Die Bike Arena kann nur die verkauften Stücke verlässlich erfassen.","ask":"Welche Vereinbarungen berücksichtigen beide Interessen?","options":["Für die gemeinsame Auswertung zählen beide die verkauften Stücke aus dem Aktionssortiment.","Block meldet seine Beratungen zusätzlich und kennzeichnet sie als eigene Standortzahl.","Block darf im Newsletter keine Beratung erwähnen, solange diese nicht die gemeinsame Kennzahl ist.","Leer schätzt die Beratungen anhand der Familienzahl und meldet sie als echte Werte.","Die Partner legen vorab fest, welche Zahlen für das gemeinsame Ziel gelten und welche Zusatzdaten sind.","Sie geben einen gemeinsamen Prozentwert an, indem sie Beratungen und Stückzahlen zusammenzählen."],"answer":[0,1,4],"why":"Die gemeinsame Messung bleibt einheitlich. Block kann gleichzeitig sein Beratungsinteresse verfolgen und die Zahl getrennt ausweisen.","hint":"Ein gemeinsames Ziel und ein zusätzlicher Ladenwert können nebeneinanderstehen.","steps":"Formuliere eine Abmachung für beide und eine ergänzende Abmachung nur für Block.","example":"Ein Laden kann Gespräche für sich auswerten, ohne sie in einen Vergleich von Stückzahlen zu mischen.","c":2,"sourceRefs":["Handlungssituation","M1","M2"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Passender Aushang","scene":"Übungsvariante: Block entscheidet sich für das Schaufenster, um Menschen direkt vor Ort auf die Aktion hinzuweisen.","ask":"Welche Einträge passen zu diesem Beschluss?","options":["Werbeträger: der gedruckte Aushang. Werbemittel: das Schaufenster.","Freigabe und Ausdruck bis Freitag um 14 Uhr in der Vorbereitungswoche.","Block versendet den Schaufensterhinweis am Montag um 8 Uhr als Newsletter.","Werbeträger: das Schaufenster. Werbemittel: der gedruckte Aushang.","Der Aushang kann beim Vorbeigehen auf Zubehör und Beratung aufmerksam machen.","Der Aushang ersetzt die Stückzahlmeldung am Montag nach der Aktion."],"answer":[1,3,4],"why":"Das Schaufenster ist der Platz, der Aushang die gestaltete Werbung. Block gibt ihn bis Freitag um 14 Uhr frei, druckt ihn und bringt ihn ab Dienstag zur Öffnung an.","hint":"Nimm in M3 ausdrücklich die Schaufenster-Zeile.","steps":"Ordne Platz, Werbung, Vorteil und Termine der richtigen Zeile zu.","example":"Ein Aushang kann vor Ort ansprechbar machen, was später persönlich beraten wird.","c":4,"sourceRefs":["M1","M3"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zahlen ohne Verwechslung melden","scene":"Übungsvariante: Block zählt in der Aktionswoche 48 verkaufte Stücke und 35 Beratungen. Die Bike Arena verkauft 62 Stück.","ask":"Welche Meldungen sind für die gemeinsame Erfolgskontrolle brauchbar?","options":["Block meldet 35 Beratungen als gemeinsamen Aktionswert.","Block meldet 48 Stück des Aktionssortiments.","Die Bike Arena meldet 62 Stück des Aktionssortiments.","Global Bike erhält nur 145 als Summe aus Verkäufen und Beratungen.","Die Zahlen werden am Montag nach der Aktion gemeldet, mit Standort und Zeitraum.","Die Vergleichswoche wird künftig mit 48 und 62 Stück angegeben."],"answer":[1,2,4],"why":"Für das gemeinsame Ziel zählen 48 und 62 verkaufte Stücke aus der Aktionswoche. Die 35 Beratungen können getrennt bleiben. Die früheren Vergleichswerte ändern sich nicht.","hint":"Kreise die Zahlen ein, die dieselbe Einheit haben.","steps":"Ordne jede Zahl einer Tätigkeit und einer Woche zu. Übernimm nur die passenden Stückzahlen.","example":"Eine zusätzliche Kennzahl wird nicht Teil der gemeinsamen Zahl, bloß weil sie in derselben Nachricht steht.","c":3,"sourceRefs":["M2","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zielerreichung vergleichen","scene":"Übungsvariante: Ziel sind jeweils mindestens 10 % mehr verkaufte Aktionsartikel. Block meldet 44 und die Bike Arena 64 Stück. Ausgangswerte: 40 und 60.","ask":"Welche Aussagen stimmen?","options":["Block hat exakt 10 % mehr verkauft und damit sein Ziel erreicht.","Die Bike Arena hat ebenfalls exakt 10 % mehr verkauft, weil beide vier Stück mehr verkauft haben.","Die Bike Arena brauchte mindestens 66 Stück und verfehlt ihr Ziel um zwei Stück.","Beide Läden haben das Ziel allein deshalb erreicht, weil beide Mengen gestiegen sind.","Nur die Bike Arena hat das Ziel erreicht, weil sie insgesamt mehr verkauft hat.","Die Veränderung wird jeweils am eigenen Ausgangswert des Ladens gemessen."],"answer":[0,2,5],"why":"Vier zusätzliche Stücke entsprechen bei 40 Stück genau 10 %, bei 60 Stück rund 6,7 %. Deshalb erreicht Block das jeweilige Ziel, die Bike Arena noch nicht.","hint":"Der Prozentzuwachs hängt von der Ausgangsmenge ab.","steps":"Berechne zuerst 10 % der 40 bzw. 60 Stück. Vergleiche für jeden Laden Ist und Ziel.","example":"Vier zusätzliche Stücke auf 20 entsprechen 20 %, auf 40 nur 10 %.","c":0,"sourceRefs":["M2","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Einen Anstieg einordnen","scene":"Übungsvariante: Beim Treffen nach der Aktion sind die Verkäufe gegenüber der Vergleichswoche in beiden Läden gestiegen.","ask":"Welche Auswertung kann Jan fachlich vertreten?","options":["Die gemessenen Stückzahlen mit den vereinbarten Zielwerten vergleichen.","Aus dem Anstieg allein schließen, dass die Werbung ihn vollständig verursacht hat.","Weitere mögliche Einflüsse im Bericht offenlassen.","Für beide Verkaufsergebnisse die Stückzahlen derselben Warengruppe und vergleichbarer Öffnungstage prüfen.","Den späteren Versandtermin als Nachweis für die Werbewirkung ausgeben.","Die Kennzahl nachträglich austauschen, falls ein Geschäft das Ziel verfehlt."],"answer":[0,2,3],"why":"Die Zahlen zeigen, wie die Läden zum Ziel stehen. Auch andere Einflüsse können Verkäufe verändern. Deshalb gehören eine saubere Abgrenzung und eine vorsichtige Deutung in den Bericht.","hint":"Trenne Ergebnis und Erklärung für das Ergebnis.","steps":"Schreibe für eine Rückmeldung zuerst den messbaren Vergleich auf und danach, was daraus offenbleibt.","example":"Ein Verkaufsanstieg kann mit einer gelungenen Werbung zusammenfallen, ohne ihre genaue Wirkung zu belegen.","c":0,"sourceRefs":["M2"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Freigabefähiger Plan","scene":"Übungsvariante: Ein Entwurf enthält für Block lediglich „Newsletter am Montag“ und für die Bike Arena „Aufsteller bei Gelegenheit“. Das gemeinsame Ziel ist schon vollständig formuliert.","ask":"Welche Ergänzungen sollte Jan vor der Freigabe verlangen?","options":["Für Block die zuständige Ladenleitung, ihre Frist und die Versandzeit festhalten.","Für den Aufsteller die Druckfreigabe, Drucklieferung und den Einsatztermin eintragen.","Die fertigen Werbemittel ersetzen alle Terminangaben im Plan.","Für beide Werbeplätze erklären, warum sie zur jeweiligen Kundschaft passen.","Als Erfolgskontrolle nur beide Werbemittel nebeneinander betrachten.","Die fehlenden Fristen erst nach Erscheinen der Werbung ergänzen."],"answer":[0,1,3],"why":"Ein freigabefähiger Werbeplan legt Gründe, Zuständigkeiten, Freigabe und Einsatz fest. Ein fertiger Entwurf allein klärt keine Abläufe.","hint":"Lies den knappen Entwurf so, als müsstest du ihn morgen ausführen.","steps":"Prüfe je Laden: Welche Person muss wann handeln, und warum ist dieser Werbeplatz vorgesehen?","example":"„Schild am Eingang ab Freitag“ sagt noch nicht, wann die Druckerei ihre Freigabe braucht.","c":1,"sourceRefs":["M1","M3","M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Das Treffen vorbereiten","scene":"Übungsvariante: Mittwoch vor der Frühjahrsaktion. Jan bittet dich, die Abstimmung zwischen Block und der Bike Arena zu leiten. Die Angaben in M1 bis M3 gelten weiterhin. Dein erster Schwerpunkt soll auch in deinen späteren Entscheidungen sichtbar bleiben.","ask":"Womit eröffnest du die Abstimmung?","options":["Du legst die bisherigen Stückzahlen und die verfügbaren Messdaten beider Läden nebeneinander.","Du fragst beide Ladenleitungen, was ihnen bei der Aktion besonders wichtig ist.","Du markierst die frühesten Fristen und die Personen, die für Freigaben zuständig sind.","Du trennst vergleichbare Verkaufsdaten von den zusätzlichen Beratungszahlen bei Block.","Du fasst die Wünsche zu Beratung und Selbstbedienung zusammen und lässt beide Läden sie ergänzen.","Du skizzierst die Arbeitsschritte vom Entwurf bis zum Einsatz und markierst, welche Zusagen noch fehlen."],"consequences":["Die beiden Ausgangswerte sind sichtbar. Diese Grundlage hilft euch beim Formulieren eines messbaren Ziels.","Die Ladenleitungen können ihre verschiedenen Erwartungen nennen, bevor sie eine Entscheidung treffen.","Die Druckfreigabe kann gleich im Gespräch mit den richtigen Verantwortlichen geklärt werden.","Du verhinderst, dass Beratung und Stückverkauf versehentlich in einen Messwert geraten.","Die unterschiedlichen Bedürfnisse beider Standorte bleiben für die Werbeauswahl sichtbar.","Der Ablauf zeigt, an welchen offenen Zusagen die spätere Umsetzung hängt."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Wähle einen Schwerpunkt für die Abstimmung. Alle drei Perspektiven gehören zum Plan.","steps":"Überlege, welche Information du in jedem späteren Schritt wieder nutzen möchtest.","example":"Ein Start bei den Ausgangsdaten kann später beim Ziel und bei der Erfolgskontrolle wieder aufgegriffen werden.","c":2,"sourceRefs":["Handlungssituation","M1","M2","M3"],"id":24,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"title":"Das Ziel vereinbaren","scene":"Die Beteiligten akzeptieren Stückzahlen als gemeinsame Kennzahl. Jetzt soll der Plan eindeutig sagen, wie der Erfolg je Laden beurteilt wird.","ask":"Wie bereitest du die Einigung über einen Zielwert vor?","options":["Du rechnest einen möglichen prozentualen Zuwachs getrennt für 40 und 60 Stück in absolute Zielmengen um.","Du besprichst die gewünschten Zuwächse mit beiden Ladenleitungen und klärst, welche Werte beide verbindlich mittragen.","Du legst verbindlich fest, welche Artikel, Tage und Kassenmeldungen in die gemeinsame Messung eingehen.","Du stellst zwei vollständige Ziele mit der gleichen Kennzahl und unterschiedlichen Zielwerten gegenüber.","Du hältst fest, welche eigene Kennzahl Block zusätzlich erfasst und wofür der gemeinsame Zielwert steht.","Du trägst Zielgrößen, Meldezeitpunkt und Verantwortung für die Erfassung in das gemeinsame Planblatt ein."],"consequences":["Die Zielmengen lassen sich später für jeden Laden mit der passenden Ausgangsmenge vergleichen.","Beide Ladenleitungen können einem konkreten Ziel zustimmen und wissen, worauf die gemeinsame Auswertung schaut.","Die Messung bekommt klare Grenzen, sodass beide Standorte dieselben Kriterien anwenden.","Die Beteiligten können die beiden Vorschläge vergleichen, ohne die Messmethode zu wechseln.","Block kann sein Beratungsinteresse berücksichtigen, während die gemeinsame Auswertung einheitlich bleibt.","Zur Zahl kommt eine gesicherte Zuständigkeit für die spätere Meldung hinzu."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Knüpfe an den Schwerpunkt deiner Eröffnung an und beachte die vorhandenen Zahlen.","steps":"Prüfe, welchen Aspekt dein Vorschlag für die gemeinsam vereinbarte Kennzahl besonders gut klärt.","example":"Dasselbe Plus in Stück kann bei zwei unterschiedlichen Ausgangswerten ein anderes prozentuales Plus bedeuten.","c":0,"sourceRefs":["M2","M5"],"id":25,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Werbeplätze wählen","scene":"Für Block stehen Newsletter und Schaufenster zur Auswahl. Für die Bike Arena gibt es Aufsteller und Hauptgang. Alle im Plan genannten Plätze sind zum Zeitpunkt des Treffens noch möglich.","ask":"Wie begründest du die Auswahl je Standort?","options":["Du vergleichst die Werbeträger mit den dokumentierten Besuchszeiten und wählst pro Standort eine passende Möglichkeit.","Du lässt beide Ladenleitungen erklären, wo sie in ihrem Laden die gewünschte Kundschaft am besten erreichen.","Du legst die vier möglichen Werbeplätze samt Fristen auf die Zeitachse und klärst, bei welchen die Freigaben rechtzeitig klappen.","Du prüfst anhand der Ladenprofile, ob die Werbung vor dem Besuch, beim Ankommen oder erst im Laden wirken soll.","Du fragst nach den unterschiedlichen Wünschen zu Beratung und Orientierung und lässt sie als Begründung in die Standortzeilen aufnehmen.","Du klärst je Platz, wer den Druck oder Versand übernimmt und ob die dafür nötige Freigabe gesichert werden kann."],"consequences":["Besuchszeit und Ort der Ansprache sind als überprüfbare Gründe dokumentiert.","Die Auswahl passt zu dem Wissen, das die Ladenleitungen über Menschen und Abläufe vor Ort haben.","Vor der Auswahl ist sichtbar, welche Einsätze innerhalb der Vorbereitungsfrist möglich sind.","Du trennst verschiedene Zeitpunkte des Kontakts und kannst den Platz gezielt begründen.","Die Begründung hält die unterschiedlichen Bedürfnisse beider Standorte im Plan fest.","Die gewählten Plätze sind mit den zuständigen Personen und Arbeitsschritten verbunden."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Behalte die Zielgruppe im Blick. Entscheide, wie du die Auswahl im Plan belegst.","steps":"Ordne deinem bisherigen Schwerpunkt einen konkreten Prüfschritt in M1 oder M3 zu.","example":"Ein Newsletter und ein Aushang können dieselbe Botschaft an unterschiedlichen Punkten des Einkaufs zeigen.","c":4,"sourceRefs":["M1","M3","M4"],"id":26,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Einen Engpass bearbeiten","scene":"Übungsvariante: Die Bike Arena meldet kurz vor 16 Uhr, dass die Druckfreigabe für den Eingang nicht mehr rechtzeitig klappt. Der Werbeplatz am Hauptgang ist noch verfügbar.","ask":"Wie reagierst du, ohne die gemeinsame Aktion aus dem Blick zu verlieren?","options":["Du prüfst anhand von M3, ab wann das Hauptgangschild wirken kann und wodurch es die Zielgruppe im Laden erreicht.","Du fragst die Ladenleitung, wie sie Familien vom Eingang zur Fläche leiten kann, wenn der Hinweis am Hauptgang steht.","Du nimmst den nicht mehr erreichbaren Drucktermin aus dem Plan und setzt die Fristen für den Hauptgang ein.","Du hältst in der Planzeile fest, welche Annahme zur Erreichbarkeit nach dem Ortswechsel noch geprüft werden muss.","Du stimmst mit der Bike Arena und Sarah ab, wie sich der Ersatz im gemeinsamen Text und in der jeweiligen Ladenfassung zeigt.","Du sicherst die Freigabe der Bike Arena bis Freitag um 12 Uhr und klärst den eigenen Druck und Einsatz am Dienstag."],"consequences":["Der Ersatz ist mit einem konkreten Platz und einem Einsatztermin begründet.","Die Ladenleitung kann eine Wegführung vorschlagen, die unter den geänderten Bedingungen funktioniert.","Die Zeitachse zeigt nur noch Schritte, die der Laden tatsächlich ausführen kann.","Eine offene Annahme bleibt sichtbar, statt als erwiesene Wirkung in den Plan zu rutschen.","Die Botschaft lässt sich mit den Beteiligten anpassen, ohne die gemeinsame Aktion aufzugeben.","Die Bike Arena hat einen ausführbaren Ersatz mit Zuständigkeit und Frist."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Prüfe deine bisherige Entscheidung und welche Bedingungen sich geändert haben.","steps":"Streiche den verpassten Druckweg und prüfe die Ersatzmöglichkeit mit deinem Schwerpunkt.","example":"Bei einem Wechsel des Werbeplatzes ändern sich oft die Zuständigkeit und die Wirkung am jeweiligen Ort.","c":1,"sourceRefs":["M1","M3","M4"],"id":27,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Plan abstimmen","scene":"Newsletter für Block und ein Hinweisschild am Hauptgang in Leer sollen in die Endfassung. Jan will den Plan vor der Freigabe noch einmal prüfen lassen.","ask":"Wie machst du den Plan vor der Freigabe belastbar?","options":["Du prüfst für beide Standortzeilen, ob die Begründung und sämtliche Ist- und Zielwerte auf die richtigen Angaben in M1 bis M3 zurückgehen.","Du zeigst beiden Ladenleitungen ihre Planzeile und lässt sie Auftrag, Termine und Begründung bestätigen.","Du gehst Entwurf, Freigabe, Druck oder Versand und Einsatz in der Reihenfolge durch und ergänzt jede fehlende Verantwortung.","Du kontrollierst, dass Newsletter und Hauptgangschild zum jeweiligen Kontaktzeitpunkt passen und die Messgröße gleich bleibt.","Du klärst offen, ob sich eine Person mit ihrer Zusage übernommen hat, und hältst vereinbarte Änderungen fest.","Du ergänzt neben den Einsatzterminen eine Meldezeile für den Montag nach der Aktion und legst fest, wer für welchen Laden meldet."],"consequences":["Es ist nachvollziehbar, aus welchem Material die Begründungen und Planwerte stammen.","Die zugesagten Aufgaben sind mit den Personen abgestimmt, die sie tatsächlich ausführen.","Abhängigkeiten und noch offene Aufgaben lassen sich vor dem Einsatz erkennen.","Der Plan verbindet passende Werbeplätze mit einer gemeinsamen Auswertung.","Unklare Zusagen lassen sich rechtzeitig ändern und werden für alle sichtbar.","Die Erfolgskontrolle bleibt auch nach dem sichtbaren Ende der Werbung eingeplant."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Lies den Plan als Person, die nach ihm arbeiten soll.","steps":"Prüfe je Laden, was nach deiner bisherigen Entscheidung noch abgesichert werden muss.","example":"Ein Freigabevermerk hilft wenig, wenn die folgende Meldung überhaupt keiner zuständigen Person zugeordnet wurde.","c":3,"sourceRefs":["M2","M3","M5"],"id":28,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Das Ergebnis zurückmelden","scene":"Übungsvariante: Am Montag nach der Aktion liegen beide Stückzahlen vor. Jan bittet um eine kurze, nachvollziehbare Rückmeldung zu euren Entscheidungen.","ask":"Wie schließt du die Kette ab?","options":["Du zeigst pro Laden Ausgangsmenge, Zielmenge und Aktionsmenge und erklärst, welche Schlüsse der Vergleich trägt.","Du besprichst den Zielvergleich mit beiden Ladenleitungen und fragst, was bei Beratung und Orientierung aus ihrer Sicht gut lief.","Du prüfst, ob beide Meldungen die vereinbarten Artikel und Tage umfassen, und legst Plan und Zahlen gemeinsam ab.","Du hältst im Ergebnis fest, welche Aussage am Kassenwert belegt ist und welche nach einer weiteren Beobachtung fragt.","Du lässt die Partner eine konkrete Verbesserung für die nächste Aktion vereinbaren und legst fest, wer sie prüft.","Du dokumentierst die erreichte oder verfehlte Zielgröße und ergänzt eine offene Zuständigkeit für die nächste Planung."],"consequences":["Der Vergleich je Standort zeigt verständlich, ob die vereinbarte Zielgröße erreicht wurde.","Die Beteiligten verbinden ihre Erfahrungen mit der gemeinsamen Zahl, ohne Einzelbeobachtungen als Stückzahlen auszugeben.","Die nächste Auswertung kann auf vollständige und vergleichbare Unterlagen zurückgreifen.","Du trennst den belegten Befund von einer noch offenen Erklärung.","Die Rückmeldung wird als gemeinsam abgestimmter nächster Schritt weitergeführt.","Das Ergebnis geht mit einem eindeutigen Auftrag in die nächste Planungsrunde ein."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Führe den Schwerpunkt aus deiner bisherigen Kette bis in die Rückmeldung weiter.","steps":"Schaue kurz auf deine vorangehende Entscheidung. Benenne, welche Information du im Ergebnis wieder aufgreifst.","example":"Eine gute Rückmeldung trennt das gemessene Ergebnis von der Frage, welchen Anteil die Werbung daran hatte.","c":0,"sourceRefs":["M2","M5"],"id":29,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]}];
